import{_ as t,o as r,c as s,a2 as a}from"./chunks/framework.C9_66ieh.js";const u=JSON.parse('{"title":"MCP (unified hub)","description":"","frontmatter":{},"headers":[],"relativePath":"mcp.md","filePath":"mcp.md","lastUpdated":1785285564000}'),d={name:"mcp.md"};function o(i,e,n,c,l,p){return r(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="mcp-unified-hub" tabindex="-1">MCP (unified hub) <a class="header-anchor" href="#mcp-unified-hub" aria-label="Permalink to &quot;MCP (unified hub)&quot;">​</a></h1><p>TrueDeck maintains a <strong>single MCP server list</strong> and injects it into every supported agent client so you configure once.</p><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Flows into</th></tr></thead><tbody><tr><td>Memory providers</td><td></td></tr><tr><td>User MCP servers</td><td>→ <strong>TrueDeck hub map</strong> → Cursor / Claude / Grok / Codex / Gemini / <code>.mcp.json</code></td></tr><tr><td>Builtin hub MCP</td><td></td></tr></tbody></table><p>Main code: <code>electron/main/mcp-hub.ts</code><br> Agent-facing server: <code>resources/mcp-server/truedeck-mcp.mjs</code></p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Description</th></tr></thead><tbody><tr><td><strong>builtin</strong></td><td><code>truedeck-hub</code> - tools to edit the hub and tasks</td></tr><tr><td><strong>memory</strong></td><td>MCP entries derived from enabled memory providers (e.g. MemPalace)</td></tr><tr><td><strong>user</strong></td><td>Servers you add in Settings → MCP or via hub tools</td></tr></tbody></table><p>Store for user servers: <code>&lt;dataDir&gt;/mcp-servers.json</code>.</p><h2 id="settings-ui" tabindex="-1">Settings UI <a class="header-anchor" href="#settings-ui" aria-label="Permalink to &quot;Settings UI&quot;">​</a></h2><p>Settings → <strong>MCP</strong>:</p><ul><li>List all entries (enable/disable user servers; memory ones toggled under memory backends)</li><li>Add server: name, command, args</li><li>Remove user servers</li><li>Sync / export helpers (export Cursor-style JSON)</li></ul><p>Docker-based memory commands are discouraged/blocked for MemPalace-style memory (prefer native <code>mempalace-mcp</code>).</p><h2 id="built-in-hub-tools" tabindex="-1">Built-in hub tools <a class="header-anchor" href="#built-in-hub-tools" aria-label="Permalink to &quot;Built-in hub tools&quot;">​</a></h2><p>When agents connect to <strong>TrueDeck MCP Hub</strong> (<code>truedeck-hub</code>), they can call:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Description</th></tr></thead><tbody><tr><td><code>truedeck_list_mcp</code></td><td>List hub servers</td></tr><tr><td><code>truedeck_add_mcp</code></td><td>Add/update a user MCP server; auto-sync when <code>sync</code> is true (default)</td></tr><tr><td><code>truedeck_remove_mcp</code></td><td>Remove user server + re-sync</td></tr><tr><td><code>truedeck_set_mcp_enabled</code></td><td>Enable/disable user server + re-sync</td></tr><tr><td><code>truedeck_apply_mcp</code></td><td>Force-sync hub into all CLI configs (<code>projectRoot</code> for repo <code>.mcp.json</code> when set)</td></tr><tr><td><code>truedeck_export_mcp</code></td><td>Export unified map as JSON</td></tr><tr><td><code>truedeck_launch</code></td><td><strong>Primary:</strong> create goal + open live agent PTY in TrueDeck (app must be running)</td></tr><tr><td><code>truedeck_dispatch</code></td><td>Dispatch an existing task id to a live PTY</td></tr><tr><td><code>truedeck_start_pipeline</code></td><td>Start multi-agent pipeline (Feature, Bugfix, …)</td></tr><tr><td><code>truedeck_list_agents</code></td><td>List agent CLI ids</td></tr><tr><td><code>truedeck_list_roles</code></td><td>List roles (implementer, reviewer, …)</td></tr><tr><td><code>truedeck_list_pipelines</code></td><td>List pipelines</td></tr><tr><td><code>truedeck_list_tasks</code></td><td>List tasks for a project (or all)</td></tr><tr><td><code>truedeck_create_task</code></td><td>Create task record only (prefer <code>truedeck_launch</code>)</td></tr><tr><td><code>truedeck_update_task</code></td><td>Update title/body/status/assignee</td></tr><tr><td><code>truedeck_delete_task</code></td><td>Delete a task</td></tr><tr><td><code>truedeck_graph_status</code></td><td>Graphify knowledge graph status</td></tr></tbody></table><p>Deck orchestration is <strong>MCP-first</strong> (no Ctrl+B panel). Electron polls <code>deck-command-queue.json</code> and spawns real PTYs.</p><p>Protocol: stdio JSON-RPC with Content-Length framing (MCP subset). Server name <code>truedeck-hub</code>, version <code>1.0.0</code> in the script.</p><h3 id="add-mcp-example-tool-args" tabindex="-1">Add MCP example (tool args) <a class="header-anchor" href="#add-mcp-example-tool-args" aria-label="Permalink to &quot;Add MCP example (tool args)&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:/tools/my-mcp/server.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;enabled&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> &quot;sync&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>command</code> is required. Docker as the command is rejected for memory-style servers.</p><h2 id="inject-targets" tabindex="-1">Inject targets <a class="header-anchor" href="#inject-targets" aria-label="Permalink to &quot;Inject targets&quot;">​</a></h2><p>The hub writes the same stdio set into client configs for:</p><ul><li>Cursor</li><li>Claude Code</li><li>Grok</li><li>Codex</li><li>Gemini</li><li>Project <code>.mcp.json</code> (when a project root is provided)</li></ul><p>Exact paths depend on each product’s config layout (under the user home / app support dirs). Use <strong>Export</strong> / <code>truedeck_export_mcp</code> to inspect the map TrueDeck would inject.</p><h2 id="data-directory-for-the-hub-script" tabindex="-1">Data directory for the hub script <a class="header-anchor" href="#data-directory-for-the-hub-script" aria-label="Permalink to &quot;Data directory for the hub script&quot;">​</a></h2><p><code>truedeck-mcp.mjs</code> resolves data dir as:</p><ol><li><code>TRUEDECK_DATA_DIR</code> if set</li><li>Else platform defaults under <code>TrueDeck/data</code> (Windows <code>%APPDATA%</code>, macOS Application Support, Linux XDG)</li></ol><p>Keep Electron and external hub processes pointed at the same directory if you override it.</p><h2 id="memory-mcp" tabindex="-1">Memory MCP <a class="header-anchor" href="#memory-mcp" aria-label="Permalink to &quot;Memory MCP&quot;">​</a></h2><p>Memory backends (TrueMemory files, MemPalace native, OpenMemory, custom) are documented in <a href="./memory-providers">memory-providers.md</a>. They appear in the MCP list as <code>source: &#39;memory&#39;</code>. Toggle them under memory provider settings, not only the MCP tab.</p><h2 id="packaging" tabindex="-1">Packaging <a class="header-anchor" href="#packaging" aria-label="Permalink to &quot;Packaging&quot;">​</a></h2><p><code>electron-builder</code> ships <code>resources/mcp-server/**</code> as <code>extraResources</code>. Packaged apps resolve the hub script from <code>process.resourcesPath</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./architecture">Architecture</a></li><li><a href="./task-board">Task board</a> - task tools</li><li><a href="./configuration">Configuration</a></li></ul>`,34)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
